const body = $json.body || $json;
const daysAhead = Number(body.days) > 0 ? Number(body.days) : 7;
const durationMinutes = Number(body.durationMinutes) > 0 ? Number(body.durationMinutes) : 30;
const now = new Date();
const rangeEnd = new Date(now.getTime() + daysAhead * 24 * 60 * 60 * 1000);
return [{
  json: {
    rangeStartIso: now.toISOString(),
    rangeEndIso: rangeEnd.toISOString(),
    durationMinutes
  }
}];

const BUSINESS_TIMEZONE = 'Africa/Johannesburg';
const BUSINESS_START_HOUR = 9;
const BUSINESS_END_HOUR = 17;
const MAX_SLOTS = 8;
const STEP_MINUTES = 30;

const windowData = $('Compute Search Window').first().json;
const durationMinutes = windowData.durationMinutes;
const rangeStart = new Date(windowData.rangeStartIso);
const rangeEnd = new Date(windowData.rangeEndIso);

function parseGraphDate(d) {
  if (!d || !d.dateTime) return null;
  const iso = d.dateTime.endsWith('Z') ? d.dateTime : d.dateTime + 'Z';
  return new Date(iso);
}

const busyPeriods = $input.all()
  .map(item => item.json)
  .filter(ev => ev && ev.start && ev.end)
  .map(ev => ({ start: parseGraphDate(ev.start), end: parseGraphDate(ev.end) }))
  .filter(p => p.start && p.end);

function zonedParts(date) {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: BUSINESS_TIMEZONE, hour12: false, weekday: 'short', hour: 'numeric', minute: 'numeric'
  });
  const map = {};
  fmt.formatToParts(date).forEach(p => { map[p.type] = p.value; });
  return { weekday: map.weekday, hour: Number(map.hour), minute: Number(map.minute) };
}

const slots = [];
const cursor = new Date(rangeStart);
cursor.setUTCSeconds(0, 0);

while (cursor < rangeEnd && slots.length < MAX_SLOTS) {
  const parts = zonedParts(cursor);
  const isWeekday = !['Sat', 'Sun'].includes(parts.weekday);
  const withinHours = parts.hour >= BUSINESS_START_HOUR && parts.hour < BUSINESS_END_HOUR;

  if (isWeekday && withinHours) {
    const slotEnd = new Date(cursor.getTime() + durationMinutes * 60 * 1000);
    const overlaps = busyPeriods.some(b => cursor < b.end && slotEnd > b.start);
    if (!overlaps) {
      slots.push({
        startIso: cursor.toISOString(),
        endIso: slotEnd.toISOString(),
        label: new Intl.DateTimeFormat('en-ZA', {
          timeZone: BUSINESS_TIMEZONE, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'
        }).format(cursor)
      });
    }
  }
  cursor.setTime(cursor.getTime() + STEP_MINUTES * 60 * 1000);
}

return [{ json: { slots, timezone: BUSINESS_TIMEZONE } }];

const body = $json.body || $json;
const durationMinutes = Number(body.durationMinutes) > 0 ? Number(body.durationMinutes) : 30;
const start = new Date(body.startDateTime);
const end = new Date(start.getTime() + durationMinutes * 60 * 1000);
const clientName = body.clientName || 'Unknown client';
const clientPhone = body.clientPhone || 'Unknown number';
const notes = body.notes || '';

return [{
  json: {
    subject: 'Consultation - ' + clientName,
    startIso: start.toISOString(),
    endIso: end.toISOString(),
    description: 'Booked via WhatsApp bot.\nClient: ' + clientName + '\nWhatsApp: ' + clientPhone + (notes ? ('\nNotes: ' + notes) : '')
  }
}];
